[ExtensionOf(classStr(PrintMgmtNode_Sales))]
final class KPMGPrintMgmtNode_Sales_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_15231_Customer Statement DCP 14/02/2022
    /// Gets a list of valid document types for the node. A list of valid document types
    /// for the node. The results can vary based on what is configured in the application
    /// because configuration keys are used to determine this list.
    /// </summary>
    /// <returns>list </returns>
    public List getDocumentTypes()
    {
        List ret = next getDocumentTypes();

        ret.addEnd(PrintMgmtDocumentType::KPMGMultiCustAccountStatement);

        return ret;
    }
